// ============================================================
// CUSTOMS DOCUMENT CROSS-CHECKER
// Compares Invoice ↔ Packing List ↔ Bill of Lading
// Flags mismatches with line references
// ============================================================

const inv = $input.item.json.invoiceParsed || {};
const pl  = $input.item.json.packingParsed  || {};
const bol = $input.item.json.bolParsed      || {};

const discrepancies = [];
const checks = [];

function check(id, label, invVal, plVal, bolVal) {
  const strInv = String(invVal || '').trim().toLowerCase();
  const strPl  = String(plVal  || '').trim().toLowerCase();
  const strBol = String(bolVal || '').trim().toLowerCase();

  let mismatch = false;
  const mismatches = [];

  if (plVal !== undefined && strInv !== strPl) {
    mismatch = true;
    mismatches.push(`Invoice: "${invVal}" vs Packing List: "${plVal}"`);
  }
  if (bolVal !== undefined && strInv !== strBol) {
    mismatch = true;
    mismatches.push(`Invoice: "${invVal}" vs Bill of Lading: "${bolVal}"`);
  }
  if (plVal !== undefined && bolVal !== undefined && strPl !== strBol) {
    mismatch = true;
    mismatches.push(`Packing List: "${plVal}" vs Bill of Lading: "${bolVal}"`);
  }

  const result = { id, label, status: mismatch ? 'MISMATCH' : 'OK', details: mismatches.join(' | ') };
  checks.push(result);
  if (mismatch) discrepancies.push(result);
}

check('CON-001', 'Consignee / Buyer Name', inv.buyer_name, pl.consignee_name, bol.consignee_name);
check('SHP-001', 'Shipper / Seller Name', inv.seller_name, pl.shipper_name, bol.shipper_name);
check('PORT-001', 'Port of Loading', inv.port_of_loading, undefined, bol.port_of_loading);
check('PORT-002', 'Port of Discharge', inv.port_of_discharge, undefined, bol.port_of_discharge);

const bolPackages = parseFloat(bol.total_packages) || 0;
const plTotalPackages = parseFloat(pl.total_packages) || 0;
const pkgMismatch = [];
if (plTotalPackages > 0 && bolPackages > 0 && plTotalPackages !== bolPackages) {
  pkgMismatch.push(`Packing List: ${plTotalPackages} cartons vs BOL: ${bolPackages} cartons`);
}
const pkgResult = { id: 'PKG-001', label: 'Total Packages (PL vs BOL)', status: pkgMismatch.length ? 'MISMATCH' : 'OK', details: pkgMismatch.join(' | ') };
checks.push(pkgResult);
if (pkgMismatch.length) discrepancies.push(pkgResult);

const plGW  = parseFloat((pl.total_gross_weight_kg  || '').toString().replace(/[^0-9.]/g, '')) || 0;
const bolGW = parseFloat((bol.total_gross_weight_kg || '').toString().replace(/[^0-9.]/g, '')) || 0;
const gwMismatch = [];
if (plGW > 0 && bolGW > 0 && Math.abs(plGW - bolGW) > 1) {
  gwMismatch.push(`Packing List: ${plGW} kg vs BOL: ${bolGW} kg`);
}
const gwResult = { id: 'WGT-001', label: 'Total Gross Weight (PL vs BOL)', status: gwMismatch.length ? 'MISMATCH' : 'OK', details: gwMismatch.join(' | ') };
checks.push(gwResult);
if (gwMismatch.length) discrepancies.push(gwResult);

const invItems = inv.line_items || [];
const plItems  = pl.line_items  || [];
for (let i = 0; i < Math.max(invItems.length, plItems.length); i++) {
  const invItem = invItems[i];
  const plItem  = plItems[i];
  if (!invItem || !plItem) continue;

  const invHs = String(invItem.hs_code || '').replace(/[^0-9]/g, '');
  const plHs  = String(plItem.hs_code  || '').replace(/[^0-9]/g, '');
  if (invHs && plHs && invHs !== plHs) {
    const hsResult = { id: `HS-00${i+1}`, label: `HS Code — Line Item ${i+1} (Invoice vs Packing List)`, status: 'MISMATCH', details: `Invoice HS: ${invItem.hs_code} vs Packing List HS: ${plItem.hs_code} | Item: ${invItem.description || plItem.description}` };
    checks.push(hsResult); discrepancies.push(hsResult);
  } else {
    checks.push({ id: `HS-00${i+1}`, label: `HS Code — Line Item ${i+1}`, status: 'OK', details: `Both documents show HS: ${invItem.hs_code}` });
  }

  const invQty = parseFloat(invItem.quantity) || 0;
  const plQty  = parseFloat(plItem.quantity)  || 0;
  if (invQty > 0 && plQty > 0 && invQty !== plQty) {
    const qtyResult = { id: `QTY-00${i+1}`, label: `Quantity — Line Item ${i+1} (Invoice vs Packing List)`, status: 'MISMATCH', details: `Invoice: ${invQty} ${invItem.unit || ''} vs Packing List: ${plQty} ${plItem.unit || ''} | Item: ${invItem.description}` };
    checks.push(qtyResult); discrepancies.push(qtyResult);
  } else {
    checks.push({ id: `QTY-00${i+1}`, label: `Quantity — Line Item ${i+1}`, status: 'OK', details: `Both documents: ${invQty} ${invItem.unit || 'pcs'}` });
  }
}

const plMarks  = String(pl.marks_and_numbers || '').trim().toLowerCase();
const bolMarks = String(bol.shipping_marks   || '').trim().toLowerCase();
if (plMarks && bolMarks && plMarks !== bolMarks) {
  const marksResult = { id: 'MRK-001', label: 'Shipping Marks (PL vs BOL)', status: 'MISMATCH', details: `Packing List: "${pl.marks_and_numbers}" vs BOL: "${bol.shipping_marks}"` };
  checks.push(marksResult); discrepancies.push(marksResult);
} else {
  checks.push({ id: 'MRK-001', label: 'Shipping Marks', status: 'OK', details: '' });
}

const verdict = discrepancies.length === 0 ? 'READY_TO_FILE' : 'NEEDS_CORRECTION';
const totalChecks = checks.length;
const passedChecks = checks.filter(c => c.status === 'OK').length;

return {
  json: {
    shipmentRef:    $input.item.json.shipmentRef,
    submitterEmail: $input.item.json.submitterEmail,
    verdict,
    summary: { total: totalChecks, passed: passedChecks, failed: discrepancies.length },
    discrepancies,
    allChecks: checks,
    invoiceSummary: {
      invoiceNumber:   inv.invoice_number,
      invoiceDate:     inv.invoice_date,
      seller:          inv.seller_name,
      buyer:           inv.buyer_name,
      totalValue:      inv.total_invoice_value,
      currency:        inv.currency,
      incoterms:       inv.incoterms,
      countryOfOrigin: inv.country_of_origin
    },
    bolSummary: {
      bolNumber:    bol.bol_number,
      vessel:       bol.vessel_name,
      voyage:       bol.voyage_number,
      freightTerms: bol.freight_terms
    }
  }
};
